public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        int cp = str.charAt(i++);
        if (cp < 0x80) {
            size++;
        } else if (cp < 0x800) {
            size += 2;
        } else if (cp < 0xd800 || cp >= 0xe000) {
            size += 3;
        } else {
