public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] columns = line.split(",");
            if (columns.length != 3) {
                throw new IllegalArgumentException("Invalid file format");
            }
            String threadName = columns[0];
            String snapTime = columns[1];
            String snapDuration = columns[2];
            try {
                int time = Integer.parseInt(snapTime);
                int duration = Integer.parseInt(snapDuration);
                boolean isInRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range.contains(time)) {
                        isInRange = true;
                        break;
                    }
                }
                if (isInRange) {
                    threadSnapshots.add(new ThreadSnapshot(threadName, time, duration));
                }
            } catch (NumberFormatException e) {
                throw new IOException("Invalid data in file", e);
            }
        }
    }
    return threadSnapshots;
}
